

-- =============================================================
-- 00_create_database.sql
-- =============================================================

-- MySQL 8+ / MySQL Workbench
CREATE DATABASE IF NOT EXISTS biotech_analytics_practice
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_0900_ai_ci;

USE biotech_analytics_practice;
SELECT DATABASE() AS active_database;


-- =============================================================
-- 01_create_tables.sql
-- =============================================================

USE biotech_analytics_practice;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS biomarker_results;
DROP TABLE IF EXISTS experiments;
DROP TABLE IF EXISTS method_qualification;
DROP TABLE IF EXISTS quality_events;
DROP TABLE IF EXISTS stability_results;
DROP TABLE IF EXISTS assay_results;
DROP TABLE IF EXISTS dq_issues;
DROP TABLE IF EXISTS biomarkers;
DROP TABLE IF EXISTS studies;
DROP TABLE IF EXISTS labs;
DROP TABLE IF EXISTS assays;
DROP TABLE IF EXISTS programs;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE programs (
    program_id VARCHAR(10) NOT NULL,
    program_code VARCHAR(50) NOT NULL,
    modality VARCHAR(50),
    phase VARCHAR(30),
    indication VARCHAR(100),
    program_status VARCHAR(30),
    PRIMARY KEY (program_id),
    UNIQUE KEY uq_program_code (program_code)
) ENGINE=InnoDB;

CREATE TABLE assays (
    assay_id VARCHAR(10) NOT NULL,
    assay_name VARCHAR(80) NOT NULL,
    assay_category VARCHAR(50),
    canonical_unit VARCHAR(30),
    spec_low DOUBLE,
    spec_high DOUBLE,
    target_value DOUBLE,
    PRIMARY KEY (assay_id)
) ENGINE=InnoDB;

CREATE TABLE labs (
    lab_id VARCHAR(10) NOT NULL,
    lab_name VARCHAR(80) NOT NULL,
    lab_type VARCHAR(30),
    location VARCHAR(80),
    PRIMARY KEY (lab_id)
) ENGINE=InnoDB;

CREATE TABLE studies (
    study_id VARCHAR(10) NOT NULL,
    study_name VARCHAR(80),
    program_id VARCHAR(10),
    study_type VARCHAR(30),
    start_date DATE,
    study_status VARCHAR(30),
    PRIMARY KEY (study_id),
    CONSTRAINT fk_studies_program FOREIGN KEY (program_id) REFERENCES programs(program_id)
) ENGINE=InnoDB;

CREATE TABLE biomarkers (
    biomarker_id VARCHAR(10) NOT NULL,
    biomarker_name VARCHAR(50) NOT NULL,
    biomarker_class VARCHAR(30),
    unit VARCHAR(20),
    PRIMARY KEY (biomarker_id)
) ENGINE=InnoDB;

CREATE TABLE assay_results (
    result_id VARCHAR(20) NOT NULL,
    program_id VARCHAR(10),
    lot_id VARCHAR(60),
    sample_id VARCHAR(30),
    assay_id VARCHAR(10),
    lab_id VARCHAR(10),
    result_date DATE,
    result_value VARCHAR(40),
    unit VARCHAR(30),
    spec_low DOUBLE,
    spec_high DOUBLE,
    result_status VARCHAR(20),
    analyst_id VARCHAR(30),
    instrument_id VARCHAR(40),
    replicate_no INT,
    source_system VARCHAR(40),
    load_timestamp DATETIME,
    PRIMARY KEY (result_id),
    CONSTRAINT fk_assay_results_program FOREIGN KEY (program_id) REFERENCES programs(program_id),
    CONSTRAINT fk_assay_results_assay FOREIGN KEY (assay_id) REFERENCES assays(assay_id),
    CONSTRAINT fk_assay_results_lab FOREIGN KEY (lab_id) REFERENCES labs(lab_id)
) ENGINE=InnoDB;

CREATE TABLE stability_results (
    stability_id VARCHAR(20) NOT NULL,
    program_id VARCHAR(10),
    lot_id VARCHAR(60),
    assay_id VARCHAR(10),
    lab_id VARCHAR(10),
    storage_condition VARCHAR(20),
    timepoint_month INT,
    pull_date DATE,
    result_value DOUBLE,
    unit VARCHAR(30),
    baseline_value DOUBLE,
    percent_change DOUBLE,
    oot_flag CHAR(1),
    oos_flag CHAR(1),
    PRIMARY KEY (stability_id),
    CONSTRAINT fk_stability_program FOREIGN KEY (program_id) REFERENCES programs(program_id),
    CONSTRAINT fk_stability_assay FOREIGN KEY (assay_id) REFERENCES assays(assay_id),
    CONSTRAINT fk_stability_lab FOREIGN KEY (lab_id) REFERENCES labs(lab_id)
) ENGINE=InnoDB;

CREATE TABLE quality_events (
    event_id VARCHAR(20) NOT NULL,
    program_id VARCHAR(10),
    lot_id VARCHAR(60),
    assay_id VARCHAR(10),
    lab_id VARCHAR(10),
    event_type VARCHAR(30),
    open_date DATE,
    close_date DATE,
    event_status VARCHAR(20),
    root_cause_category VARCHAR(50),
    severity VARCHAR(20),
    days_open INT,
    recurrence_flag CHAR(1),
    linked_result_id VARCHAR(20),
    PRIMARY KEY (event_id),
    CONSTRAINT fk_quality_program FOREIGN KEY (program_id) REFERENCES programs(program_id),
    CONSTRAINT fk_quality_assay FOREIGN KEY (assay_id) REFERENCES assays(assay_id),
    CONSTRAINT fk_quality_lab FOREIGN KEY (lab_id) REFERENCES labs(lab_id)
) ENGINE=InnoDB;

CREATE TABLE method_qualification (
    qualification_id VARCHAR(20) NOT NULL,
    program_id VARCHAR(10),
    assay_id VARCHAR(10),
    lab_id VARCHAR(10),
    qualification_type VARCHAR(30),
    start_date DATE,
    end_date DATE,
    acceptance_criteria_met CHAR(1),
    qualification_status VARCHAR(40),
    precision_rsd DOUBLE,
    accuracy_recovery_pct DOUBLE,
    linearity_r2 DOUBLE,
    robustness_pass CHAR(1),
    cycle_time_days INT,
    PRIMARY KEY (qualification_id),
    CONSTRAINT fk_qual_program FOREIGN KEY (program_id) REFERENCES programs(program_id),
    CONSTRAINT fk_qual_assay FOREIGN KEY (assay_id) REFERENCES assays(assay_id),
    CONSTRAINT fk_qual_lab FOREIGN KEY (lab_id) REFERENCES labs(lab_id)
) ENGINE=InnoDB;

CREATE TABLE experiments (
    experiment_id VARCHAR(20) NOT NULL,
    study_id VARCHAR(10),
    run_date DATE,
    assay_platform VARCHAR(50),
    treatment VARCHAR(30),
    dose DOUBLE,
    donor_id VARCHAR(20),
    cell_line VARCHAR(40),
    operator_id VARCHAR(30),
    batch_id VARCHAR(30),
    viability_pct DOUBLE,
    response_pct DOUBLE,
    cytokine_pg_ml DOUBLE,
    source_system VARCHAR(40),
    review_status VARCHAR(30),
    PRIMARY KEY (experiment_id),
    CONSTRAINT fk_experiments_study FOREIGN KEY (study_id) REFERENCES studies(study_id)
) ENGINE=InnoDB;

CREATE TABLE biomarker_results (
    biomarker_result_id VARCHAR(20) NOT NULL,
    experiment_id VARCHAR(20),
    study_id VARCHAR(10),
    donor_id VARCHAR(20),
    treatment VARCHAR(30),
    timepoint_hr INT,
    biomarker_id VARCHAR(10),
    result_value DOUBLE,
    unit VARCHAR(20),
    qc_flag VARCHAR(20),
    replicate_no INT,
    PRIMARY KEY (biomarker_result_id),
    CONSTRAINT fk_biomarker_result_exp FOREIGN KEY (experiment_id) REFERENCES experiments(experiment_id),
    CONSTRAINT fk_biomarker_result_study FOREIGN KEY (study_id) REFERENCES studies(study_id),
    CONSTRAINT fk_biomarker_result_biomarker FOREIGN KEY (biomarker_id) REFERENCES biomarkers(biomarker_id)
) ENGINE=InnoDB;

CREATE TABLE dq_issues (
    dq_issue_id VARCHAR(20) NOT NULL,
    source_table VARCHAR(50),
    record_key VARCHAR(30),
    issue_type VARCHAR(50),
    issue_date DATE,
    severity VARCHAR(20),
    resolution_status VARCHAR(20),
    resolved_date DATE,
    PRIMARY KEY (dq_issue_id)
) ENGINE=InnoDB;


