-- 03_create_indexes.sql
-- =============================================================

USE biotech_analytics_practice;

CREATE INDEX idx_assay_results_program_assay_date ON assay_results(program_id, assay_id, result_date);
CREATE INDEX idx_assay_results_lab_status ON assay_results(lab_id, result_status);
CREATE INDEX idx_stability_lot_assay_timepoint ON stability_results(lot_id, assay_id, timepoint_month);
CREATE INDEX idx_stability_program_assay ON stability_results(program_id, assay_id);
CREATE INDEX idx_quality_events_status_type_date ON quality_events(event_status, event_type, open_date);
CREATE INDEX idx_method_qual_program_assay_lab ON method_qualification(program_id, assay_id, lab_id);
CREATE INDEX idx_experiments_study_treatment_date ON experiments(study_id, treatment, run_date);
CREATE INDEX idx_experiments_operator_review ON experiments(operator_id, review_status);
CREATE INDEX idx_biomarker_results_exp_biomarker_tp ON biomarker_results(experiment_id, biomarker_id, timepoint_hr);
CREATE INDEX idx_dq_issue_source_status ON dq_issues(source_table, resolution_status, issue_date);


-- =============================================================
-- 04_create_views.sql
-- =============================================================

USE biotech_analytics_practice;

CREATE OR REPLACE VIEW vw_qc_assay_enriched AS
SELECT
    r.result_id,
    r.program_id,
    p.program_code,
    r.lot_id,
    r.sample_id,
    r.assay_id,
    a.assay_name,
    a.assay_category,
    r.lab_id,
    l.lab_name,
    l.lab_type,
    r.result_date,
    CAST(NULLIF(TRIM(r.result_value), '') AS DECIMAL(30,10)) AS result_value_numeric,
    TRIM(r.unit) AS reported_unit,
    a.canonical_unit,
    r.spec_low,
    r.spec_high,
    r.result_status,
    r.analyst_id,
    r.instrument_id,
    r.replicate_no,
    r.source_system,
    r.load_timestamp,
    CASE WHEN r.lab_id IS NULL OR TRIM(r.lab_id) = '' THEN 1 ELSE 0 END AS missing_lab_flag,
    CASE
      WHEN CAST(NULLIF(TRIM(r.result_value), '') AS DECIMAL(30,10)) < r.spec_low
        OR CAST(NULLIF(TRIM(r.result_value), '') AS DECIMAL(30,10)) > r.spec_high
      THEN 'OOS'
      ELSE 'PASS'
    END AS recalculated_status
FROM assay_results r
LEFT JOIN programs p ON r.program_id = p.program_id
LEFT JOIN assays a ON r.assay_id = a.assay_id
LEFT JOIN labs l ON r.lab_id = l.lab_id;

CREATE OR REPLACE VIEW vw_stability_enriched AS
SELECT
    s.stability_id,
    s.program_id,
    p.program_code,
    s.lot_id,
    s.assay_id,
    a.assay_name,
    a.assay_category,
    s.lab_id,
    l.lab_name,
    l.lab_type,
    s.storage_condition,
    s.timepoint_month,
    s.pull_date,
    s.result_value,
    s.unit,
    s.baseline_value,
    s.percent_change,
    s.oot_flag,
    s.oos_flag,
    a.spec_low,
    a.spec_high,
    a.target_value
FROM stability_results s
LEFT JOIN programs p ON s.program_id = p.program_id
LEFT JOIN assays a ON s.assay_id = a.assay_id
LEFT JOIN labs l ON s.lab_id = l.lab_id;

CREATE OR REPLACE VIEW vw_quality_event_enriched AS
SELECT
    q.*,
    p.program_code,
    a.assay_name,
    l.lab_name,
    l.lab_type,
    CASE
      WHEN q.event_status = 'Open' AND q.days_open > 45 THEN 'High Aging'
      WHEN q.event_status = 'Open' AND q.days_open > 30 THEN 'Watch'
      ELSE 'Normal'
    END AS aging_bucket
FROM quality_events q
LEFT JOIN programs p ON q.program_id = p.program_id
LEFT JOIN assays a ON q.assay_id = a.assay_id
LEFT JOIN labs l ON q.lab_id = l.lab_id;

CREATE OR REPLACE VIEW vw_experiment_enriched AS
SELECT
    e.*,
    s.study_name,
    s.study_type,
    s.program_id,
    p.program_code,
    CASE WHEN e.review_status = 'Rework' THEN 1 ELSE 0 END AS rework_flag,
    CASE WHEN e.review_status = 'Pending Review' THEN 1 ELSE 0 END AS pending_review_flag
FROM experiments e
LEFT JOIN studies s ON e.study_id = s.study_id
LEFT JOIN programs p ON s.program_id = p.program_id;


-- =============================================================
-- 05_create_stored_procedures.sql
-- =============================================================

USE biotech_analytics_practice;

DROP PROCEDURE IF EXISTS usp_qc_summary;
DROP PROCEDURE IF EXISTS usp_stability_lot_detail;
DROP PROCEDURE IF EXISTS usp_method_qualification_summary;
DROP PROCEDURE IF EXISTS usp_experiment_summary;

DELIMITER $$

CREATE PROCEDURE usp_qc_summary(
    IN p_program_code VARCHAR(50),
    IN p_start_date DATE,
    IN p_end_date DATE
)
BEGIN
    SELECT
        program_code,
        assay_name,
        COALESCE(lab_type, 'Unknown') AS lab_type,
        COUNT(*) AS result_count,
        SUM(CASE WHEN result_status = 'OOS' THEN 1 ELSE 0 END) AS oos_count,
        ROUND(100.0 * SUM(CASE WHEN result_status = 'OOS' THEN 1 ELSE 0 END)
              / NULLIF(COUNT(*), 0), 2) AS oos_rate_pct
    FROM vw_qc_assay_enriched
    WHERE (p_program_code IS NULL OR program_code = p_program_code)
      AND (p_start_date IS NULL OR result_date >= p_start_date)
      AND (p_end_date IS NULL OR result_date <= p_end_date)
    GROUP BY program_code, assay_name, COALESCE(lab_type, 'Unknown')
    ORDER BY oos_rate_pct DESC, result_count DESC;
END $$

CREATE PROCEDURE usp_stability_lot_detail(
    IN p_lot_id VARCHAR(60),
    IN p_assay_id VARCHAR(10)
)
BEGIN
    WITH stability_calc AS (
        SELECT
            program_code,
            lot_id,
            assay_id,
            assay_name,
            storage_condition,
            timepoint_month,
            pull_date,
            result_value,
            baseline_value,
            percent_change,
            oot_flag,
            oos_flag,
            LAG(result_value) OVER (
                PARTITION BY lot_id, assay_id
                ORDER BY timepoint_month
            ) AS previous_result
        FROM vw_stability_enriched
        WHERE (p_lot_id IS NULL OR lot_id = p_lot_id)
          AND (p_assay_id IS NULL OR assay_id = p_assay_id)
    )
    SELECT
        *,
        ROUND(result_value - previous_result, 4) AS change_from_previous
    FROM stability_calc
    ORDER BY lot_id, assay_id, timepoint_month;
END $$

CREATE PROCEDURE usp_method_qualification_summary(
    IN p_program_id VARCHAR(10),
    IN p_assay_id VARCHAR(10),
    IN p_lab_id VARCHAR(10)
)
BEGIN
    SELECT
        mq.program_id,
        p.program_code,
        mq.assay_id,
        a.assay_name,
        mq.lab_id,
        l.lab_name,
        COUNT(*) AS qualification_count,
        SUM(CASE WHEN mq.acceptance_criteria_met = 'Y' THEN 1 ELSE 0 END) AS pass_count,
        SUM(CASE WHEN mq.acceptance_criteria_met = 'N' THEN 1 ELSE 0 END) AS fail_count,
        ROUND(100.0 * SUM(CASE WHEN mq.acceptance_criteria_met = 'Y' THEN 1 ELSE 0 END)
              / NULLIF(COUNT(*),0), 2) AS pass_rate_pct,
        ROUND(AVG(mq.cycle_time_days), 2) AS avg_cycle_time_days
    FROM method_qualification mq
    LEFT JOIN programs p ON mq.program_id = p.program_id
    LEFT JOIN assays a ON mq.assay_id = a.assay_id
    LEFT JOIN labs l ON mq.lab_id = l.lab_id
    WHERE (p_program_id IS NULL OR mq.program_id = p_program_id)
      AND (p_assay_id IS NULL OR mq.assay_id = p_assay_id)
      AND (p_lab_id IS NULL OR mq.lab_id = p_lab_id)
    GROUP BY mq.program_id, p.program_code, mq.assay_id, a.assay_name, mq.lab_id, l.lab_name
    ORDER BY pass_rate_pct ASC, avg_cycle_time_days DESC;
END $$

CREATE PROCEDURE usp_experiment_summary(
    IN p_study_id VARCHAR(10),
    IN p_treatment VARCHAR(30)
)
BEGIN
    SELECT
        study_id,
        treatment,
        COUNT(*) AS experiment_count,
        ROUND(AVG(response_pct),2) AS avg_response_pct,
        ROUND(STDDEV_SAMP(response_pct),2) AS response_sd,
        ROUND(AVG(viability_pct),2) AS avg_viability_pct,
        SUM(CASE WHEN review_status='Rework' THEN 1 ELSE 0 END) AS rework_count,
        ROUND(100.0 * SUM(CASE WHEN review_status='Rework' THEN 1 ELSE 0 END)
              / NULLIF(COUNT(*),0), 2) AS rework_rate_pct
    FROM experiments
    WHERE (p_study_id IS NULL OR study_id = p_study_id)
      AND (p_treatment IS NULL OR treatment = p_treatment)
    GROUP BY study_id, treatment
    ORDER BY study_id, avg_response_pct DESC;
END $$

DELIMITER ;


-- =============================================================
-- 06_data_quality_checks.sql
-- =============================================================

USE biotech_analytics_practice;

-- Duplicate natural keys in assay data.
SELECT
    program_id, lot_id, sample_id, assay_id, lab_id, result_date, replicate_no,
    COUNT(*) AS duplicate_count
FROM assay_results
GROUP BY program_id, lot_id, sample_id, assay_id, lab_id, result_date, replicate_no
HAVING COUNT(*) > 1
ORDER BY duplicate_count DESC;

-- Missing laboratory identifiers.
SELECT *
FROM assay_results
WHERE lab_id IS NULL OR TRIM(lab_id) = '';

-- Unit mismatches versus assay master.
SELECT
    r.result_id, r.assay_id, a.assay_name,
    r.unit AS reported_unit,
    a.canonical_unit
FROM assay_results r
JOIN assays a ON r.assay_id = a.assay_id
WHERE TRIM(r.unit) <> TRIM(a.canonical_unit);

-- Source result status versus independent recalculation.
SELECT
    result_id, program_code, assay_name,
    result_value_numeric, spec_low, spec_high,
    result_status, recalculated_status
FROM vw_qc_assay_enriched
WHERE result_status <> recalculated_status;

-- Open data-quality issues.
SELECT
    source_table, issue_type, severity,
    COUNT(*) AS open_issue_count
FROM dq_issues
WHERE resolution_status = 'Open'
GROUP BY source_table, issue_type, severity
ORDER BY open_issue_count DESC;

-- Orphan checks.
SELECT COUNT(*) AS orphan_programs
FROM assay_results r
LEFT JOIN programs p ON r.program_id = p.program_id
WHERE r.program_id IS NOT NULL AND p.program_id IS NULL;

SELECT COUNT(*) AS orphan_assays
FROM assay_results r
LEFT JOIN assays a ON r.assay_id = a.assay_id
WHERE r.assay_id IS NOT NULL AND a.assay_id IS NULL;

-- Value completeness.
SELECT
    COUNT(*) AS total_results,
    SUM(CASE WHEN result_value IS NULL OR TRIM(result_value)='' THEN 1 ELSE 0 END) AS missing_result_values,
    SUM(CASE WHEN spec_low IS NULL OR spec_high IS NULL THEN 1 ELSE 0 END) AS missing_specification_rows
FROM assay_results;


-- =============================================================
-- 07_ultragenyx_analysis_queries.sql
-- =============================================================

USE biotech_analytics_practice;

-- 1) Which programs and assays have the highest OOS rate?
SELECT
    p.program_code,
    a.assay_name,
    COUNT(*) AS total_results,
    SUM(CASE WHEN ar.result_status='OOS' THEN 1 ELSE 0 END) AS oos_results,
    ROUND(
        100.0 * SUM(CASE WHEN ar.result_status='OOS' THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*),0), 2
    ) AS oos_rate_pct
FROM assay_results ar
LEFT JOIN programs p ON ar.program_id=p.program_id
LEFT JOIN assays a ON ar.assay_id=a.assay_id
GROUP BY p.program_code, a.assay_name
ORDER BY oos_rate_pct DESC, total_results DESC;

-- 2) Top 3 assays by OOS rate inside each program.
WITH assay_oos AS (
    SELECT
        p.program_code,
        a.assay_name,
        COUNT(*) AS total_results,
        SUM(CASE WHEN ar.result_status='OOS' THEN 1 ELSE 0 END) AS oos_results,
        ROUND(
            100.0 * SUM(CASE WHEN ar.result_status='OOS' THEN 1 ELSE 0 END)
            / NULLIF(COUNT(*),0), 2
        ) AS oos_rate_pct
    FROM assay_results ar
    LEFT JOIN programs p ON ar.program_id=p.program_id
    LEFT JOIN assays a ON ar.assay_id=a.assay_id
    GROUP BY p.program_code, a.assay_name
),
ranked AS (
    SELECT *,
           DENSE_RANK() OVER (
               PARTITION BY program_code
               ORDER BY oos_rate_pct DESC
           ) AS oos_rank
    FROM assay_oos
)
SELECT *
FROM ranked
WHERE oos_rank <= 3
ORDER BY program_code, oos_rank, assay_name;

-- 3) Stability change from the previous timepoint.
WITH stability_change AS (
    SELECT
        s.*,
        LAG(result_value) OVER (
            PARTITION BY lot_id, assay_id
            ORDER BY timepoint_month
        ) AS previous_result
    FROM vw_stability_enriched s
)
SELECT
    program_code,
    lot_id,
    assay_name,
    storage_condition,
    timepoint_month,
    result_value,
    previous_result,
    ROUND(result_value - previous_result,4) AS change_from_previous,
    percent_change,
    oot_flag,
    oos_flag
FROM stability_change
ORDER BY lot_id, assay_name, timepoint_month;

-- 4) Lots with the greatest absolute movement from baseline.
SELECT
    program_code,
    lot_id,
    assay_name,
    MAX(ABS(percent_change)) AS max_abs_percent_change,
    SUM(CASE WHEN oot_flag='Y' THEN 1 ELSE 0 END) AS oot_points,
    SUM(CASE WHEN oos_flag='Y' THEN 1 ELSE 0 END) AS oos_points
FROM vw_stability_enriched
GROUP BY program_code, lot_id, assay_name
ORDER BY max_abs_percent_change DESC;

-- 5) Internal versus external laboratory OOS performance.
SELECT
    a.assay_name,
    COALESCE(l.lab_type,'Unknown') AS lab_type,
    COUNT(*) AS result_count,
    ROUND(AVG(CAST(ar.result_value AS DECIMAL(30,10))),4) AS avg_result,
    ROUND(STDDEV_SAMP(CAST(ar.result_value AS DECIMAL(30,10))),4) AS result_sd,
    SUM(CASE WHEN ar.result_status='OOS' THEN 1 ELSE 0 END) AS oos_count,
    ROUND(
        100.0 * SUM(CASE WHEN ar.result_status='OOS' THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*),0),2
    ) AS oos_rate_pct
FROM assay_results ar
LEFT JOIN assays a ON ar.assay_id=a.assay_id
LEFT JOIN labs l ON ar.lab_id=l.lab_id
GROUP BY a.assay_name, COALESCE(l.lab_type,'Unknown')
ORDER BY a.assay_name, oos_rate_pct DESC;

-- 6) Open quality-event aging and recurrence risk.
SELECT
    program_code,
    event_type,
    root_cause_category,
    severity,
    COUNT(*) AS event_count,
    ROUND(AVG(days_open),2) AS avg_days_open,
    SUM(CASE WHEN recurrence_flag='Y' THEN 1 ELSE 0 END) AS recurring_events
FROM vw_quality_event_enriched
WHERE event_status='Open'
GROUP BY program_code, event_type, root_cause_category, severity
ORDER BY avg_days_open DESC, recurring_events DESC;

-- 7) What drove method-qualification failure?
SELECT
    mq.qualification_id,
    p.program_code,
    a.assay_name,
    l.lab_name,
    mq.qualification_type,
    mq.precision_rsd,
    mq.accuracy_recovery_pct,
    mq.linearity_r2,
    mq.robustness_pass,
    mq.acceptance_criteria_met,
    CASE
        WHEN mq.precision_rsd > 15 THEN 'Precision'
        WHEN mq.accuracy_recovery_pct NOT BETWEEN 85 AND 115 THEN 'Accuracy'
        WHEN mq.linearity_r2 < 0.97 THEN 'Linearity'
        WHEN mq.robustness_pass='N' THEN 'Robustness'
        ELSE 'Pass'
    END AS primary_failure_reason,
    mq.cycle_time_days
FROM method_qualification mq
LEFT JOIN programs p ON mq.program_id=p.program_id
LEFT JOIN assays a ON mq.assay_id=a.assay_id
LEFT JOIN labs l ON mq.lab_id=l.lab_id
ORDER BY mq.acceptance_criteria_met, mq.cycle_time_days DESC;

