-- =============================================================
-- 08_elevatebio_analysis_queries.sql
-- =============================================================

USE biotech_analytics_practice;

-- 1) Which treatment produces the strongest response while maintaining viability?
SELECT
    treatment,
    COUNT(*) AS experiment_count,
    ROUND(AVG(response_pct),2) AS avg_response_pct,
    ROUND(STDDEV_SAMP(response_pct),2) AS response_sd,
    ROUND(AVG(viability_pct),2) AS avg_viability_pct,
    ROUND(AVG(cytokine_pg_ml),2) AS avg_cytokine_pg_ml,
    ROUND(
        100.0 * SUM(CASE WHEN review_status='Rework' THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*),0),2
    ) AS rework_rate_pct
FROM experiments
GROUP BY treatment
ORDER BY avg_response_pct DESC;

-- 2) Treatment response by dose.
SELECT
    treatment,
    dose,
    COUNT(*) AS experiment_count,
    ROUND(AVG(response_pct),2) AS avg_response_pct,
    ROUND(STDDEV_SAMP(response_pct),2) AS response_sd,
    ROUND(AVG(viability_pct),2) AS avg_viability_pct
FROM experiments
GROUP BY treatment, dose
ORDER BY treatment, dose;

-- 3) Which donors contribute the most variability?
WITH donor_stats AS (
    SELECT
        treatment,
        donor_id,
        COUNT(*) AS n,
        AVG(response_pct) AS avg_response_pct,
        STDDEV_SAMP(response_pct) AS response_sd
    FROM experiments
    GROUP BY treatment, donor_id
)
SELECT
    treatment,
    donor_id,
    n,
    ROUND(avg_response_pct,2) AS avg_response_pct,
    ROUND(response_sd,2) AS response_sd,
    DENSE_RANK() OVER (
        PARTITION BY treatment
        ORDER BY response_sd DESC
    ) AS variability_rank
FROM donor_stats
WHERE n >= 2
ORDER BY treatment, variability_rank;

-- 4) Where are rework and pending-review rates highest?
SELECT
    study_id,
    assay_platform,
    operator_id,
    source_system,
    COUNT(*) AS experiment_count,
    SUM(CASE WHEN review_status='Rework' THEN 1 ELSE 0 END) AS rework_count,
    SUM(CASE WHEN review_status='Pending Review' THEN 1 ELSE 0 END) AS pending_review_count,
    ROUND(
        100.0 * SUM(CASE WHEN review_status='Rework' THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*),0),2
    ) AS rework_rate_pct
FROM experiments
GROUP BY study_id, assay_platform, operator_id, source_system
ORDER BY rework_rate_pct DESC, experiment_count DESC;

-- 5) Study-level performance summary.
WITH exp AS (
    SELECT
        study_id,
        COUNT(*) AS experiment_count,
        AVG(response_pct) AS avg_response_pct,
        STDDEV_SAMP(response_pct) AS response_sd,
        AVG(viability_pct) AS avg_viability_pct,
        SUM(CASE WHEN review_status='Rework' THEN 1 ELSE 0 END) AS rework_count,
        SUM(CASE WHEN review_status='Pending Review' THEN 1 ELSE 0 END) AS pending_review_count
    FROM experiments
    GROUP BY study_id
)
SELECT
    s.study_id,
    s.study_name,
    s.study_type,
    s.study_status,
    e.experiment_count,
    ROUND(e.avg_response_pct,2) AS avg_response_pct,
    ROUND(e.response_sd,2) AS response_sd,
    ROUND(e.avg_viability_pct,2) AS avg_viability_pct,
    e.rework_count,
    e.pending_review_count
FROM studies s
LEFT JOIN exp e ON s.study_id=e.study_id
ORDER BY avg_response_pct DESC;

-- 6) Biomarker-response dataset for Power BI or Python correlation work.
SELECT
    e.study_id,
    e.experiment_id,
    e.treatment,
    e.dose,
    e.donor_id,
    e.response_pct,
    e.viability_pct,
    b.biomarker_name,
    b.biomarker_class,
    br.timepoint_hr,
    br.result_value AS biomarker_result,
    br.qc_flag,
    br.replicate_no
FROM experiments e
JOIN biomarker_results br ON e.experiment_id=br.experiment_id
JOIN biomarkers b ON br.biomarker_id=b.biomarker_id
ORDER BY e.study_id, e.experiment_id, b.biomarker_name, br.timepoint_hr;

-- 7) Biomarker summary by treatment and timepoint.
SELECT
    b.biomarker_name,
    br.treatment,
    br.timepoint_hr,
    COUNT(*) AS result_count,
    ROUND(AVG(br.result_value),2) AS avg_biomarker_result,
    ROUND(STDDEV_SAMP(br.result_value),2) AS biomarker_sd
FROM biomarker_results br
JOIN biomarkers b ON br.biomarker_id=b.biomarker_id
WHERE br.qc_flag='PASS'
GROUP BY b.biomarker_name, br.treatment, br.timepoint_hr
ORDER BY b.biomarker_name, br.treatment, br.timepoint_hr;

